14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let mut final_len = args.len();
25	    let mut raw_args = clap_lex::RawArgs::new(args);
26	
27	    // A multicall binary chooses its applet from the file name it was invoked
28	    // as, just like the parser reinterprets `argv[0]` as the first word. The
29	    // resolved applet is inserted right after `argv[0]` so the regular loop
30	    // descends into it; from then on completion is scoped to that applet and
31	    // never sees the aggregate command's root.
32	    //
33	    // `arg_index` addresses the words the caller passed, where `argv[0]` is
34	    // index 0. The inserted word sits at index 1, so a cursor on any later word
35	    // moves one position to the right.
36	    let mut arg_index = arg_index;
37	    if cmd.is_multicall_set() {
38	        let mut argv0_cursor = raw_args.cursor();
39	        if let Some(argv0) = raw_args.next_os(&mut argv0_cursor) {
40	            if let Some(applet) = std::path::Path::new(argv0)
41	                .file_stem()
42	                .and_then(|file_stem| file_stem.to_str())
43	            {
44	                // Borrow `cmd` through an owned name so `raw_args` can be mutated.
45	                let applet = applet.to_owned();
46	                if cmd.find_subcommand(&applet).is_none() {
47	                    return Err(std::io::Error::other(format!(
48	                        "unrecognized multicall command `{applet}`"
49	                    )));
50	                }
51	                raw_args.insert(&argv0_cursor, [OsString::from(applet)]);
52	                final_len += 1;
53	                if arg_index != 0 {
54	                    arg_index += 1;
55	                }
56	            }
57	        }
58	    }
59	
60	    // A cursor at or past the final word names nothing to complete. (Shells
61	    // that complete a freshly typed empty word append it to `args` and address
62	    // its index instead, so it is still completed normally.)
63	    if arg_index >= final_len {
64	        return Ok(Vec::new());
65	    }
66	
67	    let mut cursor = raw_args.cursor();
68	    let mut target_cursor = raw_args.cursor();
69	    raw_args.seek(
70	        &mut target_cursor,
71	        clap_lex::SeekFrom::Start(arg_index as u64),
72	    );
73	    // As we loop, `cursor` will always be pointing to the next item
74	    raw_args.next_os(&mut target_cursor);
75	    debug!("complete: target_cursor={target_cursor:?}");
76	
77	    if !cmd.is_no_binary_name_set() {
78	        raw_args.next_os(&mut cursor);
79	    }
80	
81	    let mut current_cmd = &*cmd;
82	    let mut pos_index = 1;
83	    let mut is_escaped = false;
84	    let mut next_state = ParseState::ValueDone;
85	    let mut used_args = Vec::<clap::Id>::new();
86	    // Once a committed word selected an external subcommand, every remaining
87	    // word belongs to that external program and is never completed here.
88	    let mut in_external = false;
89	    while let Some(arg) = raw_args.next(&mut cursor) {
90	        let current_state = next_state;
91	        next_state = ParseState::ValueDone;
92	        debug!(
93	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
94	            arg.to_value_os(),
95	        );
96	        if let ParseState::Opt(state) = &current_state {
97	            // A value terminator ends a multi-value option regardless of the
98	            // word's shape: unlike a flag-like word, it never starts a new
99	            // argument, and unlike any other word, it is never one of the
100	            // option's values. A flag-shaped terminator only wins over flag
101	            // parsing when the option accepts hyphen values, matching the
102	            // parser's precedence.
103	            let opt = state.opt;
104	            if is_value_terminator(opt, &arg)
105	                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
106	            {
107	                if cursor == target_cursor {
108	                    // The cursor sits on the terminator itself. Complete as if
109	                    // it had already been submitted and an empty word followed,
110	                    // so ordinary completion resumes and the terminator is not
111	                    // offered as a candidate.
112	                    raw_args.insert(&target_cursor, [OsString::new()]);
113	                    let mut word_cursor = target_cursor;
114	                    let word = raw_args
115	                        .next(&mut word_cursor)
116	                        .expect("an empty word was just inserted");
117	                    return complete_arg(
118	                        &word,
119	                        current_cmd,
120	                        current_dir,
121	                        pos_index,
122	                        is_escaped,
123	                        ParseState::ValueDone,
124	                        &used_args,
125	                    );
126	                }
127	                next_state = ParseState::ValueDone;
128	                continue;
129	            }
130	        }
131	        if in_external {
132	            // A committed word already selected an external subcommand; this
133	            // word (and every later one) is an argument of that external
134	            // program. Its command line is unknown, so rather than falling
135	            // back to the current command's subcommands, options, or
136	            // positionals, completion succeeds with an empty set.
137	            if cursor == target_cursor {
138	                return Ok(Vec::new());
139	            }
140	            continue;
141	        }
142	
143	        if cursor == target_cursor {
144	            return complete_arg(
145	                &arg,
146	                current_cmd,
147	                current_dir,
148	                pos_index,
149	                is_escaped,
150	                current_state,
151	                &used_args,
152	            );
153	        }
154	
155	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
156	            if let Ok(value) = arg.to_value() {
157	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
158	                    current_cmd = next_cmd;
159	                    pos_index = 1;
160	                    used_args.clear();
161	                    continue;
162	                }
163	                // An unknown plain word, with no positional slot left to
164	                // fill, selects an external subcommand: the parser routes
165	                // everything after it to that external program. Flag-like
166	                // words and the escape are still parsed as flags, matching
167	                // that precedence, and an empty word is a cursor placeholder
168	                // rather than a program name.
169	                if current_cmd.is_allow_external_subcommands_set()
170	                    && !arg.is_empty()
171	                    && !arg.is_escape()
172	                    && arg.to_long().is_none()
173	                    && arg.to_short().is_none()
174	                    && find_positional(current_cmd, pos_index, false).is_none()
175	                {
176	                    in_external = true;
177	                    continue;
178	                }
179	            }
180	        }
181	
182	        // A strict delimited group whose previous word opened another fragment
183	        // (a trailing delimiter) or went invalid owns the next word outright: a
184	        // flag, the `--` escape, or a subcommand name is then another value of
185	        // the group, never a scope switch. A continuation word that fills the
186	        // group closes it; otherwise the group stays pending for its remaining
187	        // fragments.
188	        if let ParseState::Opt(state) = &current_state {
189	            if state.is_strict_group() && (state.open || state.invalid) {
190	                let mut state = state.clone();
191	                state.observe(arg.to_value_os(), false);
192	                next_state =
193	                    if !state.invalid && !state.open && state.used.len() == state.capacity() {
194	                        ParseState::ValueDone
195	                    } else {
196	                        ParseState::Opt(state)
197	                    };
198	                continue;
199	            }
200	        }
201	
202	        if is_escaped {
203	            (next_state, pos_index) =
204	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
205	        } else if arg.is_escape() {
206	            is_escaped = true;
207	            // Like the parser, `--` jumps straight to a `last(true)`
208	            // positional, skipping any unfilled positionals.
209	            if let Some(last_index) = current_cmd
210	                .get_positionals()
211	                .filter(|p| p.is_last_set())
212	                .filter_map(|p| p.get_index())
213	                .max()
214	            {
215	                pos_index = last_index;
216	            }
217	        } else if opt_allows_hyphen(&current_state, &arg) {
218	            match current_state {
219	                ParseState::Opt(mut state) => {
220	                    state.observe(arg.to_value_os(), false);
221	                    next_state = state.finish();
222	                }
223	                _ => unreachable!("else branch is only reachable in Opt state"),
224	            }
225	        } else if let Some((flag, value)) = arg.to_long() {
226	            if let Ok(flag) = flag {
227	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
228	
229	                if let Some(opt) = opt {
230	                    record_used_arg(&mut used_args, opt.get_id());
231	                    if opt.get_num_args().expect("built").takes_values() {
232	                        // An attached value (`--opt=value`) counts toward the
233	                        // option's values just like a space-separated one, so
234	                        // that completing after `--opt=value` sees the same
235	                        // state as completing after `--opt value`.
236	                        // An empty attached value (`--opt=`) types no value
237	                        // yet, so the option stays pending.
238	                        let mut state = OptState::new(opt);
239	                        if let Some(value) = value.filter(|v| !v.is_empty()) {
240	                            state.observe(value, true);
241	                        }
242	                        next_state = state.finish();
243	                    };
244	                } else if pos_allows_hyphen(current_cmd, pos_index) {
245	                    (next_state, pos_index) =
246	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
247	                }
248	            }
249	        } else if let Some(short) = arg.to_short() {
250	            let (_, matched_opts, takes_value_opt, mut short) =
251	                parse_shortflags(current_cmd, short);
252	            for opt in &matched_opts {
253	                record_used_arg(&mut used_args, opt.get_id());
254	            }
255	            if let Some(opt) = takes_value_opt {
256	                // An attached value (`-ovalue`, `-o=value`) counts toward the
257	                // option's values just like a space-separated one. An empty
258	                // attached value (`-o=`) types no value yet, so the option
259	                // stays pending instead of being treated as satisfied.
260	                let mut state = OptState::new(opt);
261	                if let Some(value) = short
262	                    .next_value_os()
263	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
264	                    .filter(|v| !v.is_empty())
265	                {
266	                    state.observe(value, true);
267	                }
268	                next_state = state.finish();
269	            } else if pos_allows_hyphen(current_cmd, pos_index) {
270	                (next_state, pos_index) =
271	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
272	            }
273	        } else {
274	            match current_state {
275	                ParseState::ValueDone | ParseState::Pos(..) => {
276	                    (next_state, pos_index) =
277	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
278	                }
279	                ParseState::Opt(mut state) => {
280	                    state.observe(arg.to_value_os(), false);
281	                    next_state = state.finish();
282	                }
283	            }
284	        }
285	    }
286	
287	    Err(std::io::Error::other("no completion generated"))
288	}
