641	fn complete_option(
642	    arg: &clap_lex::ParsedArg<'_>,
643	    cmd: &clap::Command,
644	    current_dir: Option<&std::path::Path>,
645	) -> Vec<CompletionCandidate> {
646	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
647	    let mut completions = Vec::<CompletionCandidate>::new();
648	    if arg.is_empty() {
649	        completions.extend(longs_and_visible_aliases(cmd));
650	        completions.extend(hidden_longs_aliases(cmd));
651	
652	        let dash_or_arg = if arg.is_empty() {
653	            "-".into()
654	        } else {
655	            arg.to_value_os().to_string_lossy()
656	        };
657	        completions.extend(
658	            shorts_and_visible_aliases(cmd)
659	                .into_iter()
660	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
661	        );
662	    } else if arg.is_stdio() {
663	        // HACK: Assuming knowledge of is_stdio
664	        let dash_or_arg = if arg.is_empty() {
665	            "-".into()
666	        } else {
667	            arg.to_value_os().to_string_lossy()
668	        };
669	        completions.extend(
670	            shorts_and_visible_aliases(cmd)
671	                .into_iter()
672	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
673	        );
674	
675	        completions.extend(longs_and_visible_aliases(cmd));
676	        completions.extend(hidden_longs_aliases(cmd));
677	    } else if arg.is_escape() {
678	        // HACK: Assuming knowledge of is_escape
679	        completions.extend(longs_and_visible_aliases(cmd));
680	        completions.extend(hidden_longs_aliases(cmd));
681	    } else if let Some((flag, value)) = arg.to_long() {
682	        if let Ok(flag) = flag {
683	            if let Some(value) = value {
684	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
685	                    if is_strict_group_arg(arg) {
686	                        // The whole attached word is the delimited group being
687	                        // typed, so its committed fragments are validated in
688	                        // place and only the fragment after the last delimiter
689	                        // is offered; the flag spelling is re-prefixed below.
690	                        if let Some(value) = value.to_str() {
691	                            let state = OptState::new(arg);
692	                            completions.extend(
693	                                complete_strict_group(value, &state)
694	                                    .into_iter()
695	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
696	                            );
697	                        }
698	                    } else {
699	                        completions.extend(
700	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
701	                                .into_iter()
702	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
703	                        );
704	                    }
705	                }
706	            } else {
707	                completions.extend(
708	                    longs_and_visible_aliases(cmd)
709	                        .into_iter()
710	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
711	                );
712	                completions.extend(
713	                    hidden_longs_aliases(cmd)
714	                        .into_iter()
715	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
716	                );
717	            }
718	        }
719	    } else if let Some(short) = arg.to_short() {
720	        if !short.is_negative_number() {
721	            // Find the first takes_values option.
722	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
723	
724	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
725	            if let Some(opt) = takes_value_opt {
726	                let mut peek_short = short.clone();
727	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
728	                    short.next_flag();
729	                    true
730	                } else {
731	                    false
732	                };
733	
734	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
735	                let group_completions = if is_strict_group_arg(opt) {
736	                    value
737	                        .to_str()
738	                        .map(|value| complete_strict_group(value, &OptState::new(opt)))
739	                        .unwrap_or_default()
740	                } else {
741	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
742	                };
743	                completions.extend(group_completions.into_iter().map(|comp| {
744	                    let sep = if has_equal { "=" } else { "" };
745	                    comp.add_prefix(format!("-{leading_flags}{sep}"))
746	                }));
747	            } else {
748	                completions.extend(
749	                    shorts_and_visible_aliases(cmd)
750	                        .into_iter()
751	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
752	                );
753	            }
754	        }
755	    }
756	    debug!("complete_option: completions={completions:?}");
757	    completions
758	}
