760	fn complete_arg_value(
761	    value: Result<&str, &OsStr>,
762	    arg: &clap::Arg,
763	    current_dir: Option<&std::path::Path>,
764	    arg_index: usize,
765	) -> Vec<CompletionCandidate> {
766	    let mut values = Vec::new();
767	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
768	
769	    let (prefix, value) =
770	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
771	
772	    let value_os = match value {
773	        Ok(value) => OsStr::new(value),
774	        Err(value_os) => value_os,
775	    };
776	
777	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
778	        values.extend(completer.complete_at(arg_index, value_os));
779	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
780	        values.extend(complete_value_candidates(
781	            value_os,
782	            completer.value_candidates(),
783	        ));
784	    } else if let Some(possible_values) = possible_values(arg) {
785	        if let Ok(value) = value {
786	            values.extend(complete_candidates_str(
787	                value,
788	                possible_value_candidates(possible_values),
789	            ));
790	        }
791	    } else {
792	        match arg.get_value_hint() {
793	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
794	                // Should not complete
795	            }
796	            clap::ValueHint::AnyPath => {
797	                values.extend(complete_path(value_os, current_dir, &|_| true));
798	            }
799	            clap::ValueHint::FilePath => {
800	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
801	            }
802	            clap::ValueHint::DirPath => {
803	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
804	            }
805	            clap::ValueHint::ExecutablePath => {
806	                use is_executable::IsExecutable;
807	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
808	            }
809	            clap::ValueHint::CommandName
810	            | clap::ValueHint::CommandString
811	            | clap::ValueHint::CommandWithArguments
812	            | clap::ValueHint::Username
813	            | clap::ValueHint::Hostname
814	            | clap::ValueHint::Url
815	            | clap::ValueHint::EmailAddress => {
816	                // No completion implementation
817	            }
818	            _ => {
819	                // Safe-ish fallback
820	                values.extend(complete_path(value_os, current_dir, &|_| true));
821	            }
822	        }
823	
824	        values.sort();
825	    }
826	
827	    if let Some(prefix) = prefix {
828	        values = values
829	            .into_iter()
830	            .map(|comp| comp.add_prefix(prefix))
831	            .collect();
832	    }
833	    values = values
834	        .into_iter()
835	        .map(|comp| {
836	            if comp.get_tag().is_some() {
837	                comp
838	            } else {
839	                comp.tag(Some(arg.to_string().into()))
840	            }
841	        })
842	        .collect();
843	
844	    debug!("complete_arg_value: values={values:?}");
845	    values
846	}
