1031	/// Parse the short flags and find the first `takes_values` option.
1032	///
1033	/// Returns the raw leading flags, every matched argument, the first
1034	/// `takes_values` option (if any), and the remaining unparsed flags.
1035	fn parse_shortflags<'c, 's>(
1036	    cmd: &'c clap::Command,
1037	    mut short: clap_lex::ShortFlags<'s>,
1038	) -> (
1039	    String,
1040	    Vec<&'c clap::Arg>,
1041	    Option<&'c clap::Arg>,
1042	    clap_lex::ShortFlags<'s>,
1043	) {
1044	    let takes_value_opt;
1045	    let mut matched_opts = Vec::new();
1046	    let mut leading_flags = String::new();
1047	    // Find the first takes_values option.
1048	    loop {
1049	        match short.next_flag() {
1050	            Some(Ok(opt)) => {
1051	                leading_flags.push(opt);
1052	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
1053	                if let Some(opt) = opt {
1054	                    matched_opts.push(opt);
1055	                }
1056	                if opt
1057	                    .map(|o| o.get_num_args().expect("built").takes_values())
1058	                    .unwrap_or(false)
1059	                {
1060	                    takes_value_opt = opt;
1061	                    break;
1062	                }
1063	            }
1064	            Some(Err(_)) | None => {
1065	                takes_value_opt = None;
1066	                break;
1067	            }
1068	        }
1069	    }
1070	
1071	    (leading_flags, matched_opts, takes_value_opt, short)
1072	}
