1075	/// including visible and hidden aliases.
1076	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
1077	    arg.get_long() == Some(flag)
1078	        || arg
1079	            .get_all_aliases()
1080	            .is_some_and(|aliases| aliases.contains(&flag))
1081	}
