1084	/// including visible and hidden aliases.
1085	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
1086	    arg.get_short() == Some(flag)
1087	        || arg
1088	            .get_all_short_aliases()
1089	            .is_some_and(|aliases| aliases.contains(&flag))
