1092	/// Remove argument candidates that are unavailable given the arguments
1093	/// already present on the command line.
1094	///
1095	/// Two rules apply:
1096	/// - Non-multiple argument groups: once any member of such a group is on the
1097	///   command line, every member of that group (including the selected one and
1098	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
1099	/// - Explicit conflicts: a candidate that conflicts with an already-used
1100	///   argument is removed; conflicts only need to be declared on one side.
1101	///
1102	/// Anything that is not an argument candidate (positional values,
1103	/// subcommands, custom candidates) is left untouched.
1104	fn filter_unavailable_args(
1105	    completions: &mut Vec<CompletionCandidate>,
1106	    cmd: &clap::Command,
1107	    used_args: &[clap::Id],
1108	) {
1109	    if used_args.is_empty() {
1110	        return;
1111	    }
1112	
1113	    // Members of non-multiple groups that already have a member present.
1114	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
1115	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
1116	        let members: Vec<&clap::Id> = group.get_args().collect();
1117	        if members
1118	            .iter()
1119	            .any(|id| used_args.iter().any(|used| used == *id))
1120	        {
1121	            excluded_by_group.extend(members.into_iter().cloned());
1122	        }
1123	    }
1124	
1125	    completions.retain(|candidate| {
1126	        let Some(arg) = candidate
1127	            .get_id()
1128	            .and_then(|id| id.strip_prefix("arg::"))
1129	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
1130	        else {
1131	            return true;
1132	        };
1133	        if excluded_by_group.contains(arg.get_id()) {
1134	            return false;
1135	        }
1136	        !used_args.iter().any(|used_id| {
1137	            cmd.get_arguments()
1138	                .find(|a| a.get_id() == used_id)
1139	                .is_some_and(|used| args_conflict(cmd, arg, used))
1140	        })
1141	    });
1142	}
