1144	/// Record an argument seen on the command line, keeping the first occurrence
1145	/// only so that repeating a flag neither alters filtering nor restores
1146	/// candidates already excluded.
1147	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
1148	    if !used_args.iter().any(|used| used == id) {
1149	        used_args.push(id.clone());
1150	    }
1151	}
