1196	/// Whether `first` and `second` conflict, no matter which one declares it.
1197	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
1198	    cmd.get_arg_conflicts_with(first)
1199	        .iter()
1200	        .any(|c| c.get_id() == second.get_id())
1201	        || cmd
1202	            .get_arg_conflicts_with(second)
1203	            .iter()
1204	            .any(|c| c.get_id() == first.get_id())
1205	}
1206	
1207	/// The positional the parser would fill at `pos_index`.
1208	///
1209	/// A `last(true)` positional only exists after `--`; before the terminator
1210	/// the parser rejects values for it, so it must not be completed.
1211	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
1212	    cmd.get_positionals()
1213	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
1214	}
1215	
1216	/// Parse the positional arguments. Return the new state and the new positional index.
1217	fn parse_positional<'a>(
1218	    cmd: &clap::Command,
1219	    pos_index: usize,
1220	    is_escaped: bool,
1221	    state: ParseState<'a>,
1222	) -> (ParseState<'a>, usize) {
1223	    let pos_arg = cmd
1224	        .get_positionals()
1225	        .find(|p| p.get_index() == Some(pos_index));
1226	    let num_args = pos_arg
1227	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1228	        .unwrap_or(1);
1229	
1230	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1231	        if num_args > 1 {
1232	            (ParseState::Pos((pos_index, 1)), pos_index)
1233	        } else {
1234	            if is_escaped {
1235	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1236	            } else {
1237	                (ParseState::ValueDone, pos_index + 1)
1238	            }
1239	        }
1240	    };
1241	    match state {
1242	        ParseState::ValueDone => {
1243	            update_state_with_new_positional(pos_index)
1244	        },
1245	        ParseState::Pos((prev_pos_index, num_arg)) => {
1246	            if prev_pos_index == pos_index {
1247	                if num_arg + 1 < num_args {
1248	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1249	                } else {
1250	                    if is_escaped {
1251	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1252	                    } else {
1253	                        (ParseState::ValueDone, pos_index + 1)
1254	                    }
1255	                }
1256	            } else {
1257	                update_state_with_new_positional(pos_index)
1258	            }
1259	        }
1260	        ParseState::Opt(..) => unreachable!(
1261	            "This branch won't be hit,
1262	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1263	        ),
1264	    }
1265	}
1266	
1267	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1268	    cmd.get_positionals()
1269	        .find(|a| a.get_index() == Some(pos_index))
1270	        .map(|p| p.is_allow_hyphen_values_set())
1271	        .unwrap_or(false)
1272	}
1273	
1274	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
1275	/// for, honoring the value delimiter.
1276	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
1277	    match (opt.get_value_delimiter(), value.to_str()) {
1278	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
1279	        _ => 1,
1280	    }
1281	}
1282	
1283	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1284	    let val = arg.to_value_os();
1285	    if val.starts_with("-") {
1286	        if let ParseState::Opt(state) = state {
1287	            return state.opt.is_allow_hyphen_values_set();
1288	        }
1289	    }
1290	
1291	    false
1292	}
1293	
1294	/// Whether `arg` is the standalone value terminator of a pending option.
1295	///
1296	/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
1297	/// word must consist of the terminator alone.
1298	fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1299	    opt.get_value_terminator()
1300	        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
1301	}
1302	
1303	/// Whether the parser would route this word through flag/escape parsing before
1304	/// a pending option gets to consume it as a value.
1305	fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
1306	    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
1307	}
1308	
1309	/// Whether a word can terminate a still-open multi-value option and start a
1310	/// new argument instead, the way the parser would read it.
1311	///
1312	/// While an option still owes values, the parser greedily consumes every plain
1313	/// word as one of its values; only flag-like words can switch to another
1314	/// argument. An option that accepts hyphen values consumes those too.
1315	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1316	    if arg.is_escape() {
1317	        // `--` cancels every pending option unless its values may start with `--`.
1318	        return !pending.is_allow_hyphen_values_set();
1319	    }
1320	    if !arg.to_value_os().starts_with("-") {
1321	        // A plain word is always another value of the pending option.
1322	        return false;
1323	    }
1324	    if pending.is_allow_hyphen_values_set() {
1325	        return false;
1326	    }
1327	    // `-` is a stdio/value, not a flag.
1328	    if arg.is_stdio() {
1329	        return false;
1330	    }
1331	    // Both long and short flag styles can start a new argument; unknown flags
1332	    // still switch (and error during parsing) rather than become option values.
1333	    arg.to_long().is_some() || arg.to_short().is_some()
1334	}
