75	/// Environment-activated completions for your CLI
76	///
77	/// Benefits over a CLI completion argument or subcommand
78	/// - Performance: we don't need to generate [`clap::Command`] twice or parse arguments
79	/// - Flexibility: there is no concern over it interfering with other CLI logic
80	///
81	/// **Warning:** `stdout` should not be written to before [`CompleteEnv::complete`] has had a
82	/// chance to run.
83	///
84	/// # Examples
85	///
86	/// ```rust
87	/// # use clap_complete::CompleteEnv;
88	/// fn cli() -> clap::Command {
89	///     // ...
90	/// #   clap::Command::new("empty")
91	/// }
92	///
93	/// CompleteEnv::with_factory(cli)
94	///     .complete()
95	///
96	/// // ... rest of application logic
97	/// ```
98	pub struct CompleteEnv<'s, F> {
99	    factory: F,
100	    var: &'static str,
101	    bin: Option<String>,
102	    completer: Option<String>,
103	    shells: Shells<'s>,
104	}
