106	impl<'s, F: Fn() -> clap::Command> CompleteEnv<'s, F> {
107	    /// Complete a [`clap::Command`]
108	    ///
109	    /// # Example
110	    ///
111	    /// Builder:
112	    /// ```rust
113	    /// # use clap_complete::CompleteEnv;
114	    /// fn cli() -> clap::Command {
115	    ///     // ...
116	    /// #   clap::Command::new("empty")
117	    /// }
118	    ///
119	    /// CompleteEnv::with_factory(cli)
120	    ///     .complete()
121	    ///
122	    /// // ... rest of application logic
123	    /// ```
124	    ///
125	    /// Derive:
126	    /// ```
127	    /// # use clap::Parser;
128	    /// # use clap_complete::CompleteEnv;
129	    /// use clap::CommandFactory as _;
130	    ///
131	    /// #[derive(Debug, Parser)]
132	    /// struct Cli {
133	    ///     custom: Option<String>,
134	    /// }
135	    ///
136	    /// CompleteEnv::with_factory(Cli::command)
137	    ///     .complete()
138	    ///
139	    /// // ... rest of application logic
140	    /// ```
141	    pub fn with_factory(factory: F) -> Self {
142	        Self {
143	            factory,
144	            var: "COMPLETE",
145	            bin: None,
146	            completer: None,
147	            shells: Shells::builtins(),
148	        }
149	    }
150	
151	    /// Override the environment variable used for enabling completions
152	    pub fn var(mut self, var: &'static str) -> Self {
153	        self.var = var;
154	        self
155	    }
156	
157	    /// Override the name of the binary to complete
158	    ///
159	    /// Default: `Command::get_bin_name`
160	    pub fn bin(mut self, bin: impl Into<String>) -> Self {
161	        self.bin = Some(bin.into());
162	        self
163	    }
164	
165	    /// Override the binary to call to get completions
166	    ///
167	    /// Default: `args_os()[0]`
168	    pub fn completer(mut self, completer: impl Into<String>) -> Self {
169	        self.completer = Some(completer.into());
170	        self
171	    }
172	
173	    /// Override the shells supported for completions
174	    pub fn shells(mut self, shells: Shells<'s>) -> Self {
175	        self.shells = shells;
176	        self
177	    }
178	}
