289	/// Collection of shell-specific completers
290	pub struct Shells<'s>(pub &'s [&'s dyn EnvCompleter]);
291	
292	impl<'s> Shells<'s> {
293	    /// Select all of the built-in shells
294	    pub const fn builtins() -> Self {
295	        Self(&[&Bash, &Elvish, &Fish, &Powershell, &Zsh])
296	    }
297	
298	    /// Find the specified [`EnvCompleter`]
299	    pub fn completer(&self, name: &str) -> Option<&dyn EnvCompleter> {
300	        self.0.iter().copied().find(|c| c.is(name))
301	    }
302	
303	    /// Find an [`EnvCompleter`] for the specified path to a shell.
304	    fn completer_for_path(
305	        &self,
306	        name: &std::path::Path,
307	    ) -> Result<&dyn EnvCompleter, std::io::Error> {
308	        // Strip off the parent dir in case `$SHELL` was used
309	        let name = name.file_stem().unwrap_or(name.as_os_str());
310	        // lossy won't match but this will delegate to unknown
311	        // error
312	        let name = name.to_string_lossy();
313	
314	        let shell = self.completer(&name).ok_or_else(|| {
315	            let shells = self
316	                .names()
317	                .enumerate()
318	                .fold(String::new(), |mut seed, (i, name)| {
319	                    use std::fmt::Write as _;
320	                    let prefix = if i == 0 { "" } else { ", " };
321	                    let _ = write!(&mut seed, "{prefix}`{name}`");
322	                    seed
323	                });
324	            std::io::Error::other(format!("unknown shell `{name}`, expected one of {shells}"))
325	        })?;
326	        Ok(shell)
327	    }
328	
329	    /// Collect all [`EnvCompleter::name`]s
330	    pub fn names(&self) -> impl Iterator<Item = &'static str> + 's {
331	        self.0.iter().map(|c| c.name())
332	    }
333	
334	    /// Iterate over [`EnvCompleter`]s
335	    pub fn iter(&self) -> impl Iterator<Item = &dyn EnvCompleter> {
336	        self.0.iter().copied()
337	    }
338	}
