340	/// Shell-integration for completions
341	///
342	/// This will generally be called by [`CompleteEnv`].
343	///
344	/// This handles adapting between the shell and [`completer`][crate::engine::complete()].
345	/// A `EnvCompleter` can choose how much of that lives within the registration script or
346	/// lives in [`EnvCompleter::write_complete`].
347	pub trait EnvCompleter {
348	    /// Canonical name for this shell
349	    ///
350	    /// **Post-conditions:**
351	    /// ```rust,ignore
352	    /// assert!(completer.is(completer.name()));
353	    /// ```
354	    fn name(&self) -> &'static str;
355	    /// Whether the name matches this shell
356	    ///
357	    /// This should match [`EnvCompleter::name`] and any alternative names, particularly used by
358	    /// `$SHELL`.
359	    fn is(&self, name: &str) -> bool;
360	    /// Register for completions
361	    ///
362	    /// Write the `buf` the logic needed for calling into `<VAR>=<shell> <cmd> --`, passing needed
363	    /// arguments to [`EnvCompleter::write_complete`] through the environment.
364	    ///
365	    /// - `var`: see [`CompleteEnv::var`]
366	    /// - `name`: an identifier to use in the script
367	    /// - `bin`: see [`CompleteEnv::bin`]
368	    /// - `completer`: see [`CompleteEnv::completer`]
369	    ///
370	    /// <div class="warning">
371	    ///
372	    /// **WARNING:** There are no stability guarantees between the call to
373	    /// [`EnvCompleter::write_complete`] that this generates and actually calling [`EnvCompleter::write_complete`].
374	    /// Caching the results of this call may result in invalid or no completions to be generated.
375	    ///
376	    /// </div>
377	    fn write_registration(
378	        &self,
379	        var: &str,
380	        name: &str,
381	        bin: &str,
382	        completer: &str,
383	        buf: &mut dyn std::io::Write,
384	    ) -> Result<(), std::io::Error>;
385	    /// Complete the given command
386	    ///
387	    /// Adapt information from arguments and [`EnvCompleter::write_registration`]-defined env
388	    /// variables to what is needed for [`completer`][crate::engine::complete()].
389	    ///
390	    /// Write out the [`CompletionCandidate`][crate::engine::CompletionCandidate]s in a way the shell will understand.
391	    fn write_complete(
392	        &self,
393	        cmd: &mut clap::Command,
394	        args: Vec<OsString>,
395	        current_dir: Option<&std::path::Path>,
396	        buf: &mut dyn std::io::Write,
397	    ) -> Result<(), std::io::Error>;
398	}
