249	/// Quote `s` for embedding inside fish's `--arguments` value.
250	///
251	/// Fish parses `--arguments` twice: once when sourcing the registration (the
252	/// outer double-quoted string) and again when evaluating the embedded command
253	/// substitution at completion time. Each special character must therefore
254	/// survive two rounds of unescaping, which is what this helper does that
255	/// [`fish_quote`] does not.
256	fn fish_quote_for_eval(s: &str) -> std::borrow::Cow<'_, str> {
257	    if !fish_needs_quoting(s) {
258	        return std::borrow::Cow::Borrowed(s);
259	    }
260	    let mut out = String::with_capacity(s.len() + 2);
261	    out.push('\'');
262	    for c in s.chars() {
263	        match c {
264	            '\\' => out.push_str(r"\\\\"),
265	            '\'' => out.push_str(r"\\'"),
266	            '"' => out.push_str(r#"\""#),
267	            '$' => out.push_str(r"\$"),
268	            _ => out.push(c),
269	        }
270	    }
271	    out.push('\'');
272	    std::borrow::Cow::Owned(out)
273	}
274	
275	/// Quote `s` for fish's first-pass parser.
276	///
277	/// Used for the `--command` value, where fish reads the token once when
278	/// sourcing the registration and never re-evaluates it. Single-quoting plus
279	/// escaping `\` and `'` is sufficient.
280	fn fish_quote(s: &str) -> std::borrow::Cow<'_, str> {
281	    if !fish_needs_quoting(s) {
282	        return std::borrow::Cow::Borrowed(s);
283	    }
284	    let mut out = String::with_capacity(s.len() + 2);
285	    out.push('\'');
286	    for c in s.chars() {
287	        match c {
288	            '\\' => out.push_str(r"\\"),
289	            '\'' => out.push_str(r"\'"),
290	            _ => out.push(c),
291	        }
292	    }
293	    out.push('\'');
294	    std::borrow::Cow::Owned(out)
295	}
296	
297	fn fish_needs_quoting(s: &str) -> bool {
298	    s.is_empty()
299	        || s.chars().any(|c| {
300	            !(c.is_ascii_alphanumeric()
301	                || matches!(c, '/' | '_' | '-' | '.' | ',' | '+' | '=' | ':' | '@'))
302	        })
303	}
